#include <bits/stdc++.h>
using namespace std;using U=uint64_t;const int W=7;using Bits=array<U,W>;using Line=array<char,6>;using Prog=vector<Line>;
struct Case{int r,h,w,cnt;vector<string>g;};
struct Step{Bits ones{},twos{},threes{};};
struct State{Bits b{};U hash=0;int pos[3]{},on=0,done=0,cov=0,parent=0,action=0;double score=0;};
struct Link{int parent,action;};
static U mix(U x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);}
struct Solver{Case c;int n,m,words,all;vector<pair<int,int>>ring,cells;vector<int>targets;vector<vector<Bits>>ray;Bits pat{},skirt{};vector<U>z;vector<vector<int>>ent;int dr[6]={0,1,1,0,-1,-1},dc[6]={2,1,-1,-2,-1,1};
Solver(Case cc):c(cc){int r=c.r;n=6*r;for(int i=r;i>0;i--)ring.push_back({i,r-i});for(int k=0;k<=r;k++)ring.push_back({0,r+2*k});for(int i=1;i<=r;i++)ring.push_back({i,4*r-r+i});for(int i=r+1;i<=2*r;i++)ring.push_back({i,4*r-i+r});for(int k=1;k<=r;k++)ring.push_back({2*r,3*r-2*k});for(int i=2*r-1;i>r;i--)ring.push_back({i,i-r});
vector<vector<int>>idx(c.h,vector<int>(c.w,-1));for(int i=0;i<c.h;i++)for(int j=0;j<c.w;j++)if(c.g[i][j]=='M'||c.g[i][j]=='O'){idx[i][j]=cells.size();cells.push_back({i,j});}all=cells.size();words=(all+63)/64;z.resize(all);for(int k=0;k<all;k++){z[k]=mix(k+12345);auto[i,j]=cells[k];if(c.g[i][j]=='M'){pat[k/64]|=1ULL<<(k%64);targets.push_back(k);}else for(int d=0;d<6;d++){int a=i+dr[d],b=j+dc[d];if(a>=0&&a<c.h&&b>=0&&b<c.w&&c.g[a][b]=='M')skirt[k/64]|=1ULL<<(k%64);}}m=targets.size();ray.assign(6,vector<Bits>(n));ent.assign(6,vector<int>(all));for(int d=0;d<6;d++)for(int p=0;p<n;p++){auto[i,j]=ring[p];i+=dr[d];j+=dc[d];while(i>=0&&i<c.h&&j>=0&&j<c.w&&idx[i][j]>=0){int k=idx[i][j];ray[d][p][k/64]|=1ULL<<(k%64);ent[d][k]=p;i+=dr[d];j+=dc[d];}}}
void add(Step&s,const Bits&r){for(int w=0;w<words;w++){s.threes[w]|=s.twos[w]&r[w];s.twos[w]|=s.ones[w]&r[w];s.ones[w]|=r[w];}}
vector<Step> fixed(const Prog&p,const vector<int>&ds){bool skip[6]={};for(int d:ds)skip[d]=true;int pos[6],on=0;for(int d=0;d<6;d++)pos[d]=d*c.r;vector<Step>out;for(auto l:p){Step s;for(int d=0;d<6;d++)if(!skip[d]){if(l[d]=='T')on^=1<<d;else if(l[d]=='F')pos[d]=(pos[d]+1)%n;else if(l[d]=='B')pos[d]=(pos[d]+n-1)%n;if(on>>d&1)add(s,ray[d][pos[d]]);}out.push_back(s);}return out;}
Prog search(const Prog&p,vector<int>ds,int width,int seed){int free=ds.size(),options=1<<(2*free),len=p.size();auto frames=fixed(p,ds);vector<vector<int>>next(len+1,vector<int>(all,len+5));for(int t=len-1;t>=0;t--){next[t]=next[t+1];for(int k:targets)if((frames[t].twos[k/64]&~frames[t].threes[k/64])>>(k%64)&1)next[t][k]=t;}
vector<State>beam(1);for(int d=0;d<free;d++)beam[0].pos[d]=ds[d]*c.r;vector<vector<Link>>layers(1,vector<Link>{{-1,0}});
for(int t=0;t<len-1;t++){vector<State>cand;cand.reserve(beam.size()*options);unordered_map<U,int>seen;seen.reserve(beam.size()*options);for(int pi=0;pi<(int)beam.size();pi++){auto&s=beam[pi];for(int ac=0;ac<options;ac++){State v=s;v.parent=pi;v.action=ac;for(int d=0;d<free;d++){int a=(ac>>(2*d))&3;if(a==1)v.pos[d]=(v.pos[d]+1)%n;else if(a==2)v.pos[d]=(v.pos[d]+n-1)%n;else if(a==3)v.on^=1<<d;}Step eff=frames[t];for(int d=0;d<free;d++)if(v.on>>d&1)add(eff,ray[ds[d]][v.pos[d]]);bool bad=false;for(int w=0;w<words;w++){U create=eff.twos[w]&~eff.threes[w];if(create&skirt[w]){bad=true;break;}U newb=(v.b[w]|create)&~eff.threes[w]&pat[w],diff=v.b[w]^newb;if(diff){v.cov+=__builtin_popcountll(newb)-__builtin_popcountll(v.b[w]);while(diff){int k=__builtin_ctzll(diff);v.hash^=z[w*64+k];diff&=diff-1;}v.b[w]=newb;}}if(bad)continue;if(v.cov==m){v.done++;v.cov=0;v.b={};v.hash=0;}if(v.done==c.cnt){Prog out(p.begin(),p.begin()+t+1);int act=ac,at=pi;for(int dep=t;dep>=0;dep--){for(int d=0;d<free;d++)out[dep][ds[d]]="-FBT"[(act>>(2*d))&3];if(dep){act=layers[dep][at].action;at=layers[dep][at].parent;}}return out;}
U key=v.on;for(int d=0;d<free;d++)key=key*n+v.pos[d];U span=1;for(int d=0;d<free;d++)span*=2*n;U h=v.hash^mix(key+U(v.done)*span);if(seen.find(h)!=seen.end())continue;seen.emplace(h,cand.size());
int far=0,sum=0,remaining=0;for(int k:targets)if(!(v.b[k/64]>>(k%64)&1)){int wait=min(30,next[t+1][k]-t);far=max(far,wait);sum+=wait;remaining++;}double unfilled=(c.cnt-v.done)*m-v.cov;v.score=unfilled+(seed%3==0?0.08:seed%3==1?0.15:0.0)*far+(remaining?0.05*double(sum)/remaining:0)+((mix(h+seed)&65535)/65536.0)*0.05;cand.push_back(v);
}}
if(cand.empty())return {};if((int)cand.size()>width){nth_element(cand.begin(),cand.begin()+width,cand.end(),[](auto&a,auto&b){return a.score<b.score;});cand.resize(width);}vector<Link>links;links.reserve(cand.size());for(auto&v:cand)links.push_back({v.parent,v.action});layers.push_back(move(links));beam=move(cand);}
return {};}
int verify(const Prog&p){auto frames=fixed(p,{});Bits b{};int cnt=0;for(auto&s:frames){bool good=true;for(int w=0;w<words;w++){b[w]=(b[w]|(s.twos[w]&~s.threes[w]))&~s.threes[w];if((b[w]&pat[w])!=pat[w]||(b[w]&skirt[w]))good=false;}if(good){cnt++;for(int w=0;w<words;w++)b[w]&=~pat[w];}}return cnt;}
};
Prog read(string path){ifstream f(path);string line;Prog p;while(getline(f,line)){if(line.empty())continue;istringstream s(line);Line l;bool ok=true;for(char &x:l)if(!(s>>x))ok=false;if(ok)p.push_back(l);}return p;}
void save(string path,const Prog&p){ofstream o(path+".tmp");for(auto l:p){for(int d=0;d<6;d++)o<<l[d]<<(d==5?'\n':' ');}o.close();filesystem::rename(path+".tmp",path);}
int main(int argc,char**argv){if(argc<3){cerr<<"input directory [width128] [first0] [lastall] [mode1] [seed0]\n";return 1;}ifstream f(argv[1]);int N;f>>N;vector<Case>cs(N);for(auto&c:cs){f>>c.r>>c.h>>c.w>>c.cnt;c.g.resize(c.h);for(auto&s:c.g)f>>s;}string dir=argv[2];int width=argc>3?atoi(argv[3]):128,first=argc>4?atoi(argv[4]):0,last=argc>5?min(N,atoi(argv[5])):N,mode=argc>6?atoi(argv[6]):1,seed=argc>7?atoi(argv[7]):0;
vector<int>order;if(argc>8){istringstream z(argv[8]);string tok;while(getline(z,tok,','))order.push_back(stoi(tok));}else for(int i=first;i<last;i++)order.push_back(i);for(int i:order){string path=dir+"/case_"+to_string(i)+".txt";Prog best=read(path);if(best.empty())continue;Solver s(cs[i]);int old=best.size();vector<int>used(6);for(auto l:best)for(int d=0;d<6;d++)used[d]|=(l[d]!='-');vector<vector<int>>configs;if(mode!=3)for(int d=0;d<6;d++)configs.push_back({d});if(mode==2||mode==4)for(int a=0;a<6;a++)for(int b=a+1;b<6;b++)configs.push_back({a,b});if(mode>=3)for(int a=0;a<6;a++)for(int b=a+1;b<6;b++)for(int c=b+1;c<6;c++)configs.push_back({a,b,c});stable_sort(configs.begin(),configs.end(),[&](auto&a,auto&b){int va=0,vb=0;for(int d:a)va+=used[d];for(int d:b)vb+=used[d];return va<vb;});for(auto ds:configs){auto ans=s.search(best,ds,width,seed);if(!ans.empty()&&ans.size()<best.size()&&s.verify(ans)==cs[i].cnt){best=move(ans);save(path,best);}}cerr<<i<<" old="<<old<<" best="<<best.size()<<" saved="<<old-best.size()<<'\n';}
}
